sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var responseData = current.response_body;
    var str = JSON.parse(responseData);
    var data = str.data;

    //Custody Redisign
    var updTrade = new GlideRecord(current.trade_base.sys_class_name);
    updTrade.addQuery('sys_id', current.trade_base);
    updTrade.query();
    if (updTrade.next()) {

        if (current.error_code == '200') {

            var trdMarket = updTrade.owning_business; //retrieving market GR5
            //updTrade.attribute_sync = 'Response Successful - All fields updated (200)';
            //The value has been modified as a part of defect MSSCUSTODY-3111
            //updTrade.attribute_sync = 'Response Successful - All fields updated'; //moved this line at end of if loop
            //updTrade.counterparty_reference = data[0].TradeIdentification; //MSSCUSTODY-5992: Converting to Grid
            updTrade.customer_id = data[0].CustomerIdentification;
            updTrade.account_name = data[0].SafekeepingAccountName;
            updTrade.cash_account_name = data[0].CashAccountName;
            updTrade.charge_account_identification = data[0].ChargeAccountIdentification;
            updTrade.charge_account_name = data[0].ChargeAccountName;
            // updTrade.si_purpose_code = data[0].HKSettlementInstructionPurposeCode;  //MSSCUSTODY-7123: Converting to Grid
            //updTrade.security_name = data[0].FinancialInstrumentIdentificationDescription;
            //updTrade.security_id_type = data[0].FinancialInstrumentIdentificationProductType; //MSSCUSTODY-6824: Converting to Grid
            //updTrade.contractual_settlement_date = data[0].SettlementDate;
            //updTrade.actual_settlement_date = data[0].EffectiveSettlementDate;
            //updTrade.quantity_type = data[0].QuantityType;

            updTrade.amount_settled = data[0].SettledAmount;
            //updTrade.deal_price_currency = data[0].DealPriceAmountCurrency;
            //updTrade.deal_price = data[0].DealPriceAmount;
            updTrade.charge_code = data[0].ChargeCode;
            updTrade.total_charges_amount_currency = data[0].ChargeAmountCurrency;
            updTrade.total_charges_amount = data[0].ChargeAmount;
            //updTrade.counterparty_name = data[0].CounterpartyName;
            //updTrade.counterparty_cash_account_id = data[0].CounterpartyCashAccountIdentification;
            //updTrade.counterparty_cash_account_name = data[0].CounterpartyCashAccountName;	//MSSCUSTODY-5992: Converting to Grid
            updTrade.switching_account_name = data[0].InternalAccountTransferAccountName;
            updTrade.switch_associated_account = data[0].InternalAccountTransferAssociatedAccountIdentification;
            updTrade.switch_sub_account = data[0].InternalAccountTransferAssociatedSubAccountIdentification;
            //updTrade.customer_instruction_received = data[0].ClientInstructionReceivedIndicator;
            //updTrade.hold_matched_si_indicator = data[0].HoldMatchedSettlementInstructionIndicator;
            //updTrade.legacy_previous_status = data[0].SourceSystemPreviousStatus; //MSSCUSTODY-7353: Converting to Grid
            // updTrade.reason_description_remarks_unex = data[0].AdditionalUnexecutionReasonInformation;
            // updTrade.reason_code_canc = data[0].CancellationReasonCode;
            // updTrade.reason_description_remarks_canc = data[0].AdditionalCancellationReasonInformation;
            //updTrade.remarks = data[0].SettlementInstructionProcessingAdditionalDetails;
            //updTrade.cancellation_date = data[0].CancellationDate; //MSSCUSTODY-7353: Converting to Grid
            updTrade.last_refresh_date = new GlideDateTime();
            updTrade.account_with_receiver_deliverer_custodian = data[0].ReceiversCustodianAccountIdentification + ' | ' + data[0].BuyerAccountIdentification + ' / ' + data[0].DeliverersCustodianAccountIdentification + ' | ' + data[0].SellerAccountIdentification;
            updTrade.bulk_trading_p_c_indicator = data[0].BlockTradeIndicator;
            //updTrade.buyer_seller_bic = data[0].BuyerBic + ' / ' + data[0].SellerBic;
            updTrade.buyer_seller_data_source_scheme = data[0].BuyerDataSourceSchemeType + ' | ' + data[0].BuyerDataSourceSchemeCode + ' / ' + data[0].SellerDataSourceSchemeType + ' | ' + data[0].SellerDataSourceSchemeCode;
            updTrade.buyer_seller_format = data[0].BuyerFormatOption + ' / ' + data[0].SellerFormatOption;
            updTrade.contractual_settlement_posting_value_date = data[0].ContractualValueDate;
            //updTrade.data_source_scheme = data[0].CounterpartyDataSourceSchemeType;   //MSSCUSTODY-7123: Converting to Grid
            // updTrade.depository_reference = data[0].DepositoryIdentification;
            updTrade.interest_accrued_amount = data[0].AccruedInterestAmount;
            updTrade.investment_amount_currency = data[0].InvestmentAmountCurrency;
            updTrade.investment_amount = data[0].InvestmentAmount;
            //updTrade.market_exchange_code = data[0].PlaceOfTradeMic; //MSSCUSTODY-6284: Converting to Grid
            updTrade.net_settlement_indicator = data[0].NettingIndicator;
            updTrade.net_transaction_reference = data[0].NettingTransactionIdentification;
            updTrade.no_change_of_beneficiary_owner_indicator = data[0].NoChangeOfBeneficialOwnershipIndicator;
            updTrade.number_of_days_of_interest_accrued = data[0].AccruedInterestDays;
            updTrade.number_of_child_transactions = data[0].TotalOfLinkedInstructions;
            //updTrade.propriety_code = data[0].CounterpartyDataSourceSchemeCode; //MSSCUSTODY-7123: Converting to Grid
            updTrade.receiver_deliverer_custodian = data[0].ReceiversCustodianName + ' / ' + data[0].DeliverersCustodianName;
            //updTrade.receiver_deliverer_custodian_bic = data[0].ReceiversCustodianBic + ' / ' + data[0].DeliverersCustodianBic;
            updTrade.receiver_deliverer_custodian_data_source_scheme = data[0].ReceiversCustodianDataSourceSchemeType + ' | ' + data[0].ReceiversCustodianDataSourceSchemeCode + ' / ' + data[0].DeliverersCustodianDataSourceSchemeType + ' | ' + data[0].DeliverersCustodianDataSourceSchemeCode;
            updTrade.receiver_deliverer_custodian_format = data[0].ReceiversCustodianFormatOption + ' / ' + data[0].DeliverersCustodianFormatOption;
            updTrade.stock_lending_indicator = data[0].SecuritiesLendingIndicator;
            //updTrade.swift_settlement_transaction_condition = data[0].SettlementTransactionConditionCode; //MSSCUSTODY-7353: Converting to Grid
            updTrade.swift_settlement_type_data_source_indicator = data[0].SecuritiesTransactionTypeCode;
            //updTrade.switch_indicator = data[0].InternalAccountTransferIndicator;		//MSSCUSTODY-5992: Converting to Grid
            updTrade.switch_type = data[0].InternalAccountTransferType;

            updTrade.u_value_date = data[0].ValueDate;

            var vDdt = new GlideDate();
            vDdt.setValue(data[0].ValueDate);
            updTrade.value_date = vDdt; // 5273, 7214 value date

            updTrade.interest_accrued_amount_currency = data[0].AccruedInterestAmountCurrency;
            //updTrade.bk_to_bk_info = data[0].SettlementConfirmationAdditionalDetails; //MSSCUSTODY-7353: Converting to Grid
            //Commented the below lines(94 & 95) as per the optimizer ticket number 2403291524218773 & story MSSCUSTODY-3195 as both are duplicate mappings
            //updTrade.switch_associated_account = data[0].InternalAccountTransferTransactionIdentification + ' | ' + data[0].InternalAccountTransferAccountIdentification + ' | ' + data[0].FinancialInstrumentIdentificationPrimaryIdentifier + ' | ' + data[0].SettlementQuantity;
            //updTrade.switch_sub_account = data[0].InternalAccountTransferTransactionIdentification + ' | ' + data[0].InternalAccountTransferAccountIdentification + ' | ' + data[0].FinancialInstrumentIdentificationPrimaryIdentifier + ' | ' + data[0].SettlementQuantity;
            //updTrade.cash_payment_method = data[0].CashPaymentMethod;

            //MSSCUSTODY-3591 - Converting the below fields to Grid

            // updTrade.stp_indicator = data[0].StraightThroughProcessedIndicator;
            // updTrade.isin = data[0].FinancialInstrumentIdentificationIsin;
            //.updTrade.account_standing_instructions = data[0].SecuritiesAccountStandingInstructionDetails;	//MSSCUSTODY-5992: Converting to Grid
            // updTrade.buyer_seller = data[0].BuyerName + ' / ' + data[0].SellerName;
            // updTrade.depository_reference = data[0].DepositoryIdentification + data[0].LocalCustodianIdentification;
            // updTrade.stlpos_no = data[0].MarketInfrastructureTransactionIdentification;
            // updTrade.si_payment_indicator = data[0].HKSettlementInstructionPaymentIndicator;//MSSCUSTODY-3587 : Updated with the correct name of SI payment indicator which is passed in payload
            // updTrade.cash_account_id = data[0].CashAccountIdentification;
            // updTrade.link_indicator = data[0].LinkedIndicator;
            // updTrade.local_security_code = data[0].FinancialInstrumentIdentificationLocalSecurityCode;
            // updTrade.customer_instruction_received = data[0].ClientInstructionReceivedIndicator;
            // updTrade.cash_payment_method = data[0].CashPaymentMethod;
            // updTrade.counterparty_cash_account_id = data[0].CounterpartyCashAccountIdentification;
            // updTrade.deal_price_currency = data[0].DealPriceAmountCurrency;
            // updTrade.deal_price = data[0].DealPriceAmount;
            // updTrade.buyer_seller_bic = data[0].BuyerBic + ' / ' + data[0].SellerBic;
            // updTrade.receiver_deliverer_custodian_bic = data[0].ReceiversCustodianBic + ' / ' + data[0].DeliverersCustodianBic;
            // updTrade.place_of_settlement_95a_qualifier_pset = data[0].PlaceOfSettlementBic;
            // updTrade.external_reference = data[0].InstructionIdentification;
            // updTrade.exchange_reference2 = data[0].ExchangeIdentification;
            // updTrade.counterparty_s_associate_account = data[0].CounterpartyAssociatedAccountIdentification;
            // updTrade.hold_matched_si_indicator = data[0].HoldMatchedSettlementInstructionIndicator;
            // updTrade.quantity_type = data[0].QuantityType;
            // updTrade.customer_cancellation_reference = data[0].ClientCancellationIdentification ? data[0].ClientCancellationIdentification : "";
            // //MVPDAY2 New Mapping
            // updTrade.u_client_s_seller_buyer_account = data[0].BuyerAccountIdentification + ' / ' + data[0].SellerAccountIdentification;
            // //GR5
            // if (!(trdMarket == 'DCC UK')) {
            //     updTrade.u_client_s_deliverer_receiverer_account = data[0].ReceiversCustodianAccountIdentification + ' / ' + data[0].DeliverersCustodianAccountIdentification;
            // }

            // MSSCUSTODY-3591 : On hold due to dependency from upstream
            // if (trdMarket == 'DCC MY'){
            // 	updTrade.fa = data[0].FundingArrangementIndicator ? data[0].FundingArrangementIndicator : "";
            // 	updTrade.fi_line1 = data[0].RentasRepurchaseType ? data[0].RentasRepurchaseType : "" + ' / ' +  data[0].RentasLinkedSettlementAmendmentType ? data[0].RentasLinkedSettlementAmendmentType : "";
            // 	updTrade.fi_line2_trn = data[0].RentasTransactionType ? data[0].RentasTransactionType : "";
            // 	updTrade.fi_line3_cst = data[0].RentasSellerType ? data[0].RentasSellerType : "" + ' / '  + data[0].RentasBuyerType ? data[0].RentasBuyerType : "";
            // 	updTrade.fi_line4_det = data[0].FinancialInstrumentDetachableIndicator ? data[0].FinancialInstrumentDetachableIndicator : "";
            // }


            //Below code is for GCHKDAY2
            //updTrade.a_v_indicator = data[0].AccountingAndValuationMessageStatus; //MSSCUSTODY-7353: Converting to Grid
            updTrade.u_agent_a_c = data[0].CounterpartyAccountDataTypeIdentification;
            updTrade.u_auto_amd_sts = data[0].AutoAmendmentStatus;
            updTrade.u_client_instructed_quantity_accumulated = data[0].CsdrClientInstructedPartialSettlementQuantity;
            updTrade.u_csdr_hold_status = data[0].CsdrTradeHoldReleaseStatus;
            updTrade.u_dk_indicator = data[0].DkTradeIndicator;
            // if (trdMarket != 'GC UK' && trdMarket != 'DCC UK') { // MSSCUSTODY-4701 added to fix prod issue, field will be updated only for ghss // //MSSCUSTODY-7353: Converting to Grid
            //     updTrade.u_fx_inst_sts = data[0].FxInstructionStatus;
            // }
            //updTrade.u_fxcx_indicator = data[0].FxOrderCancellationIndicator; //MSSCUSTODY-7353: Converting to Grid
            updTrade.u_late_instruction = data[0].LateTradeIndicator;
            updTrade.u_maturity_date = data[0].TerminationDate;
            updTrade.u_method_of_interest_computation = data[0].InterestComputationMethodCode;
            updTrade.u_opposite_leg_transaction_reference = data[0].RepurchaseOppositeLegTransactionIdentification;
            updTrade.u_orig_cus_sender_bic = data[0].InstructionSenderBic;
            updTrade.u_partial_settlement_allow = data[0].PartialSettlementAllowedIndicator;
            updTrade.u_primary_narr_1 = data[0].AdditionalStatus1Reason1Information;
            updTrade.u_primary_narr_2 = data[0].AdditionalStatus1Reason2Information;
            updTrade.u_primary_swift_reason_1 = data[0].SwiftStatus1Reason1Code;
            updTrade.u_primary_swift_reason_2 = data[0].SwiftStatus1Reason2Code;
            updTrade.u_primary_swift_status = data[0].SwiftStatus1Code;
            updTrade.u_reject_date = data[0].CsdrRejectedPartialSettlementDate;
            updTrade.u_reject_quantity = data[0].CsdrRejectedPartialSettlementQuantity;
            // Condition to process only if UTC time is not empty  
            if (data[0].CsdrTradeReleaseDateTimeUtc != "") {
                var dateTime = new GlideDateTime(data[0].CsdrTradeReleaseDateTimeUtc); // MSSCUSTODY:2563 Getting the value as Date/Time
                var tzConvert = new GlideScheduleDateTime(dateTime);
                tzConvert.setTimeZone("Europe/London"); // MSSCUSTODY:2563 Converting the timezone
                updTrade.u_release_date_and_time = tzConvert.getGlideDateTime().getDisplayValue(); // MSSCUSTODY:2563 Mapping the field to assign the converted time zone
            } else {
                updTrade.u_release_date_and_time = ""; // Set it to Null value
            }
            //updTrade.u_release_date_and_time = data[0].CsdrTradeReleaseDateTimeUtc;
            updTrade.u_released_quantity_accumulated = data[0].CsdrReleasedPartialSettlementQuantity;
            updTrade.u_repo_22f_rept = data[0].RepurchaseTypeCode;
            updTrade.u_repo_rate = data[0].RepurchaseRate;
            updTrade.u_repo_rate_type = data[0].RateTypeCode;
            updTrade.u_rtgs = data[0].SecuritiesRtgsIndicator;
            updTrade.u_secondary_narr_1 = data[0].AdditionalStatus2Reason1Information;
            updTrade.u_secondary_narr_2 = data[0].AdditionalStatus2Reason2Information;
            updTrade.u_secondary_swift_reason_1 = data[0].SwiftStatus2Reason1Code;
            updTrade.u_secondary_swift_reason_2 = data[0].SwiftStatus2Reason2Code;
            //GR5
            if (trdMarket != 'GC UK' && trdMarket != 'DCC UK') {
                updTrade.u_secondary_swift_reason_code_1 = data[0].SourceSystemStatus2Reason1Code;
                updTrade.u_secondary_swift_reason_code_2 = data[0].SourceSystemStatus2Reason2Code;
                updTrade.u_primary_swift_reason_code_2 = data[0].SourceSystemStatus1Reason2Code;
                // updTrade.u_trade_94b_indicator = data[0].PlaceOfTradeMic; //MSSCUSTODY-6824: Converting to Grid
                updTrade.u_primary_swift_reason_code_1 = data[0].SourceSystemStatus1Reason1Code;


            } else if (trdMarket == 'GC UK') {
                updTrade.u_secondary_swift_reason_code_1 = data[0].SwiftStatus2Reason1Code;
                updTrade.u_secondary_swift_reason_code_2 = data[0].SwiftStatus2Reason2Code;
                updTrade.u_primary_swift_reason_code_2 = data[0].SwiftStatus1Reason2Code;
            }

            updTrade.u_secondary_swift_status = data[0].SwiftStatus2Code;
            updTrade.u_stamp_duty_22f = data[0].StampDutyTaxBasisIdentification;
            updTrade.stock_borrowing_indicator = data[0].SecuritiesBorrowingIndicator;
            updTrade.u_supress_nostro = data[0].SuppressNostroMessageIndicator;
            updTrade.u_swift_settlement_transaction_condition_2 = data[0].SettlementTransactionCondition2Code;
            updTrade.u_tax_id = data[0].TaxIdentification;
            updTrade.u_termination_amount = data[0].TerminationTransactionAmount;
            updTrade.termination_amount_currency = data[0].TerminationTransactionAmountCurrency;


            // 3003 - Mapping of below fields from the payload from unity
            updTrade.u_agent_a_c = data[0].CounterpartyAccountIdentification;
            updTrade.u_agent_a_c_data_source_scheme = data[0].CounterpartyAccountDataSourceSchemeCode;
            updTrade.agent_a_c_type = data[0].CounterpartyAccountType;

            // GR5 changes - added mapping for GCS fields

            if ((trdMarket == 'GC UK') || (trdMarket == 'DCC UK')) {
                updTrade.deal_amount = data[0].TradeAmount ? data[0].TradeAmount : "";
                updTrade.comission = data[0].LocalBrokerCommissionAmount ? data[0].LocalBrokerCommissionAmount : "";
                updTrade.spec_cum_ex = data[0].SpecialCumExDividendIndicator ? data[0].SpecialCumExDividendIndicator : "";
                updTrade.acct_tot = data[0].AccountBaseCurrencySettlementAmount ? data[0].AccountBaseCurrencySettlementAmount : "";
