                // updTrade.ent_opid = data[0].CaptureUserIdentification ? data[0].CaptureUserIdentification : "";
                updTrade.stam = data[0].StampDutyTaxBasisIdentification ? data[0].StampDutyTaxBasisIdentification : "";
                updTrade.u_cancel_by = data[0].CancellationOriginatorType ? data[0].CancellationOriginatorType : "";
                updTrade.account_name = data[0].SafekeepingAccountName ? data[0].SafekeepingAccountName : "";
                updTrade.security_name = data[0].FinancialInstrumentIdentificationDescription ? data[0].FinancialInstrumentIdentificationDescription : "";
                updTrade.counterparty_name = data[0].CounterpartyName ? data[0].CounterpartyName : "";

                updTrade.no_change_of_beneficiary_owner_indicator = data[0].NoChangeOfBeneficialOwnershipIndicator ? data[0].NoChangeOfBeneficialOwnershipIndicator : "";
                updTrade.u_method_of_interest_computation = data[0].InterestComputationMethodCode ? data[0].InterestComputationMethodCode : "";
                updTrade.u_repo_rate = data[0].RepurchaseRate ? data[0].RepurchaseRate : "";
                updTrade.u_maturity_date = data[0].TerminationDate ? data[0].TerminationDate : "";
                updTrade.termination_amount_currency = data[0].TerminationTransactionAmountCurrency ? data[0].TerminationTransactionAmountCurrency : "";
                updTrade.u_termination_amount = data[0].TerminationTransactionAmount ? data[0].TerminationTransactionAmount : "";
                // MSSCUSTODY-3591 : Converting to grid
                // updTrade.remarks = data[0].TradeDescription ? data[0].TradeDescription : "";
                //updTrade.u_trade_94b_indicator = data[0].PlaceOfTradeTypeCode ? data[0].PlaceOfTradeTypeCode : ""; //MSSCUSTODY-6824: Converting to Grid

                // MSSCUSTODY-4881
                // updTrade.fx_value_date = data[0].FXValueDate ? data[0].FXValueDate : "" ;

                //MSSCUSTODY-3854 GR5 P1b changes for on-demand fields

                if (trdMarket == 'DCC UK') {
                    updTrade.nationality_declaration = data[0].AccountHolderNationalityCode ? data[0].AccountHolderNationalityCode : "";
                    updTrade.trade_price = data[0].DealMatchingPriceAmount ? data[0].DealMatchingPriceAmount : "";
                    updTrade.stamp_status = data[0].CrestStampStatusCode ? data[0].CrestStampStatusCode : "";
                    updTrade.system_of_origin = data[0].CrestOriginatingSystemCode ? data[0].CrestOriginatingSystemCode : "";
                    updTrade.client_designation = data[0].AssociatedSubAccountIdentification ? data[0].AssociatedSubAccountIdentification : "";
                    updTrade.stco_phys = data[0].PhysicallySettledIndicator ? data[0].PhysicallySettledIndicator : "";
                    updTrade.credit_party = data[0].DbvCreditPartyType ? data[0].DbvCreditPartyType : "";
                    updTrade.margin = data[0].DbvMarginPercent ? data[0].DbvMarginPercent : "";
                    updTrade.bal_cert = data[0].CrestBalanceCertificateQuantity ? data[0].CrestBalanceCertificateQuantity : "";

                } else if (trdMarket == 'GC UK') {
