                }

                updTrade.position_location = data[0].CurrentLocationCode ? data[0].CurrentLocationCode : "";
                updTrade.final_location = data[0].FinalLocationCode ? data[0].FinalLocationCode : "";
                updTrade.source_location = data[0].SourceLocationCode ? data[0].SourceLocationCode : "";
                updTrade.failed_trade = data[0].FailedTradeIndicator ? data[0].FailedTradeIndicator : "";
