                //updTrade.customer_cancellation_reference = data[0].ClientCancellationIdentification ? data[0].ClientCancellationIdentification : "";
                updTrade.fx_total_amount_reversal = data[0].FxReversalAccountBaseCurrencySettlementAmount ? data[0].FxReversalAccountBaseCurrencySettlementAmount : "";
                updTrade.fxi_td = data[0].FxStandingInstructionIndicator ? data[0].FxStandingInstructionIndicator : "";
                updTrade.fx_advice = data[0].FxAdviceIndicator ? data[0].FxAdviceIndicator : "";
                updTrade.funding = data[0].FxFundingMessageIndicator ? data[0].FxFundingMessageIndicator : "";
                updTrade.fx_rate_reversal = data[0].FxReversalRate ? data[0].FxReversalRate : "";
                updTrade.u_stamp_duty_22f = data[0].StampDutyTaxBasisIdentification ? data[0].StampDutyTaxBasisIdentification : "";
                updTrade.fx_rate_new = data[0].FxRateToAccountBaseCurrency ? data[0].FxRateToAccountBaseCurrency : "";
                updTrade.fx_deal_date = data[0].FxDealDate ? data[0].FxDealDate : "";
                updTrade.settlement_advice = data[0].SettlementAdviceIndicator ? data[0].SettlementAdviceIndicator : "";
                updTrade.consid_deal_amount_ccy = data[0].InvestmentAmountCurrency ? data[0].InvestmentAmountCurrency : "";
                updTrade.consideration_deal_amount = data[0].InvestmentAmount ? data[0].InvestmentAmount : "";
                updTrade.fee_waiver = data[0].FeeWaiverIndicator ? data[0].FeeWaiverIndicator : "";
                updTrade.stp_fail = data[0].RepairReasonInformation ? data[0].RepairReasonInformation : "";
                updTrade.fx_deal_reference = data[0].ExchangeIdentification ? data[0].ExchangeIdentification : "";
                updTrade.fx_deal_reference_reversal = data[0].FxReversalIdentification ? data[0].FxReversalIdentification : "";
                updTrade.fx_deal_date_reversal = data[0].FxReversalDealDate ? data[0].FxReversalDealDate : "";
                updTrade.fx_reversal_indicator = data[0].FxReversalStatus ? data[0].FxReversalStatus : "";
