            //Below Code is commented as the fields should not be mapped to the On-Demand
            /*
            updTrade.transaction_reference = data[0].SystemTransactionIdentification;
            updTrade.customer_reference = data[0].ClientTransactionIdentification;
            updTrade.instruction_source = data[0].SourceOfInstructionType;
            updTrade.instruction_receipt_date_time = data[0].InstructionDateTime;
